const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL = v => {try{const u=new URL(v,location.href);return ['https:','http:'].includes(u.protocol)?u.href:'#'}catch{return '#'}};
const fmt=(v,n=1)=>v==null||!Number.isFinite(v)?'—':v.toLocaleString('en-IN',{minimumFractionDigits:n,maximumFractionDigits:n});
const signed=(v,n=1)=>v==null?'—':`${v>0?'+':''}${fmt(v,n)}`;
const readStore=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const saveStore=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{toast('Browser storage is unavailable. Changes last for this session.')}};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({feed:'<path d="M4 5h16M4 12h10M4 19h16"/><circle cx="18" cy="12" r="2"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7l1-8Z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H4a1 1 0 0 0-1 1v16a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-6"/>',pin:'<path d="m9 3 6 0-1 6 4 4v2H6v-2l4-4-1-6ZM12 15v7"/>',check:'<path d="m5 12 4 4L19 6"/>',play:'<path d="m8 4 12 8-12 8V4Z"/>',pause:'<path d="M8 4v16M16 4v16"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2" fill="var(--bg)"/><circle cx="16" cy="12" r="2" fill="var(--bg)"/><circle cx="9" cy="18" r="2" fill="var(--bg)"/>',refresh:'<path d="M20 7a9 9 0 1 0 1 8M20 3v5h-5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',shield:'<path d="m12 2 8 4v6c0 6-8 10-8 10S4 18 4 12V6l8-4Z"/><path d="m8 12 3 3 5-6"/>',book:'<path d="M12 5v16M12 5C9 2 4 3 2 4v15c4-2 7-1 10 2 3-3 6-4 10-2V4c-2-1-7-2-10 1Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 18h4"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',headphones:'<path d="M3 14v-3a9 9 0 0 1 18 0v3"/><rect x="3" y="12" width="4" height="8" rx="2"/><rect x="17" y="12" width="4" height="8" rx="2"/>'})[name]||''}</svg>`;
const names={feed:'Push digest',alerts:'Alert watch',research:'Pull research',portfolio:'Portfolio & thesis'};
const catLabel={results:'Results','M&A':'M&A',management_change:'Leadership',litigation:'Regulatory',fund_raise:'Capital',capex:'Capex',pledging:'Pledging',credit_rating:'Rating',insider_trading:'Insider trade',earnings_call:'Earnings call',press_release:'Business update',dividend:'Dividend',bonus_split:'Corporate action',investor_meetings:'Investor meeting',postal_ballot:'Postal ballot',agm_egm:'AGM / EGM',unclassified:'Needs review'};
let data,backend=false,liveResearch=null,requestSequence=0,playing=false,busy=false;
const state={tab:'feed',window:24,category:'all',from:'2026-07-29',to:'2026-10-27',symbol:'KPITTECH',researchTab:'dossier',trajectory:'quarterly',portfolioTab:'watchlist',seen:readStore('finn.seen',[]),pins:readStore('finn.pins',[]),settings:readStore('finn.settings',{price_threshold_pct:3,volume_multiplier_threshold:2,categories:['results','M&A','management_change','litigation','capex','pledging','fund_raise']}),theme:readStore('finn.theme','dark'),api:readStore('finn.api',''),compact:false};
let apiToken=sessionStorage.getItem('finn.token')||'';
const api=async(path,options={})=>{const r=await fetch(`${state.api}${path}`,{...options,headers:{'Content-Type':'application/json',...(apiToken?{Authorization:`Bearer ${apiToken}`} : {}),...options.headers},signal:options.signal||AbortSignal.timeout(path==='/api/refresh'||path==='/api/research'?180000:10000)});if(!r.ok){let e;try{e=await r.json()}catch{}throw Error(e?.detail||`Request failed (${r.status})`)}return r.json()};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function modal(title,html){const d=$('#drawer');d.innerHTML=`<div class="drawer-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${html}`;d.showModal()}
function date(iso,options={day:'numeric',month:'short'}){return new Date(iso).toLocaleDateString('en-IN',{timeZone:'Asia/Kolkata',...options})}
function spark(values,colour='var(--green2)'){const v=values.filter(Number.isFinite);if(v.length<2)return '';const min=Math.min(...v),max=Math.max(...v),range=max-min||1;const points=v.map((n,i)=>`${i/(v.length-1)*100},${22-(n-min)/range*20}`).join(' ');return `<svg class="spark" viewBox="0 0 100 24" preserveAspectRatio="none" role="img" aria-label="${esc(`Price history, ${fmt(v[0])} to ${fmt(v.at(-1))}`)}"><polyline points="${points}" fill="none" stroke="${colour}" stroke-width="1.4" vector-effect="non-scaling-stroke"/></svg>`}
function nav(){return Object.entries(names).map(([key,name])=>`<button class="nav-item ${state.tab===key?'active':''}" data-action="tab" data-value="${key}" ${state.tab===key?'aria-current="page"':''}>${icon(({feed:'feed',alerts:'bolt',research:'search',portfolio:'grid'})[key])}<span>${name}</span>${key==='portfolio'&&state.pins.length?`<span class="nav-count">${state.pins.length}</span>`:''}</button>`).join('')}
function selectedFilings(){let end=new Date(data.as_of),start=new Date(end-state.window*3600000);if(state.window==='custom'){start=new Date(state.from+'T00:00:00+05:30');end=new Date(state.to+'T23:59:59+05:30')}const held=new Set(data.universe.filter(x=>x.group==='portfolio').map(x=>x.symbol));return data.filings.filter(f=>held.has(f.symbol)&&new Date(f.published_at)>=start&&new Date(f.published_at)<=end).sort((a,b)=>b.score-a.score||new Date(b.published_at)-new Date(a.published_at))}
function footer(){return `<footer class="page-foot"><span>${icon('shield',12)} Primary evidence. Traceable conclusions.</span><span class="desktop-only">FINN / ENAM Build Challenge</span><button data-action="about">Source coverage ${icon('external',10)}</button></footer>`}
function head(title,subtitle,action='refresh',button='Refresh sources'){return `<header class="page-head"><div><div class="eyebrow"><span class="dot"></span>${backend?'CONNECTED RESEARCH ENGINE':'SAVED MARKET BRIEFING'} · ${date(data.as_of,{day:'numeric',month:'short',year:'numeric'}).toUpperCase()}</div><h1>${title}</h1><p>${subtitle}</p></div><button class="button" data-action="${action}" ${busy?'disabled':''}>${icon(action==='settings'?'settings':action==='export'?'download':'refresh',14)}${busy?'Working…':button}</button></header>`}
function summary(items){const noise=items.filter(f=>f.tier==='LOW_NOISE').length,material=items.length-noise;return `<div class="signal-summary"><div><div class="big mono">${items.length}</div><div class="desc">filings in your window</div></div><span class="arrow">${icon('arrow',16)}</span><div><div class="big mono muted">${noise}</div><div class="desc">routine, tucked away</div></div><span class="arrow">${icon('arrow',16)}</span><div><div class="big mono positive">${material.toString().padStart(2,'0')}</div><div class="desc">signals to review</div></div><div class="end"><span class="small positive mono">${items.length?Math.round(noise/items.length*100):0}% less noise</span><div class="meter"><span style="width:${items.length?noise/items.length*100:0}%"></span></div></div></div>`}
function badge(text,kind=''){return `<span class="badge ${kind}">${esc(text)}</span>`}
function source(ref,label){if(!ref)return '';if(typeof ref==='string')return `<button class="source-link" data-action="evidence" data-value="${esc(ref)}">${icon('book',12)}${esc(label||data.evidence[ref]?.label||'Primary source')} ${icon('external',10)}</button>`;return `<a class="source-link" href="${esc(safeURL(ref.url))}${ref.page?'#page='+ref.page:''}" target="_blank" rel="noopener noreferrer">${icon('book',12)}${esc(label||ref.name||'Exchange filing')}${ref.page?' · PDF p. '+ref.page:''} ${icon('external',10)}</a>`}
function financialTable(f){if(!f)return '';return `<div class="financial-wrap"><table class="financial"><caption class="label" style="text-align:left;margin-bottom:6px">${esc(f.basis)} · ₹ crore</caption><thead><tr><th>Metric</th>${f.periods.map(p=>`<th>${esc(p)}</th>`).join('')}<th>QoQ</th><th>YoY</th></tr></thead><tbody>${f.rows.map(r=>`<tr><td>${esc(r.label)}</td>${r.values.map(v=>`<td>${fmt(v,r.unit==='%'?2:1)}${r.unit==='%'&&v!=null?'%':''}</td>`).join('')}<td class="${r.qoq>0?'positive':r.qoq<0?'negative':''}">${signed(r.qoq,r.unit==='%'?0:1)}${r.qoq!=null?(r.unit==='%'?' bp':'%'):''}</td><td class="${r.yoy>0?'positive':r.yoy<0?'negative':''}">${signed(r.yoy,r.unit==='%'?0:1)}${r.yoy!=null?(r.unit==='%'?' bp':'%'):''}</td></tr>`).join('')}</tbody></table></div>${f.note?`<p class="tiny-note">${esc(f.note)}</p>`:''}`}
function pinButton(id){return `<button data-action="pin" data-value="${esc(id)}" class="${state.pins.some(p=>p.id===id)?'pinned':''}" aria-label="${state.pins.some(p=>p.id===id)?'Unpin':'Pin'} finding">${icon('pin',13)} ${state.pins.some(p=>p.id===id)?'Pinned':'Pin'}</button>`}
function filingCard(f){const rich=data.rich_filings?.[f.id],seen=state.seen.includes(f.id),headline=rich?.headline||f.headline;return `<article class="card ${f.tier==='CRITICAL'?'important':''} ${seen?'reviewed':''}"><div class="card-head"><div class="company-line"><span class="company-icon">${esc(f.symbol.slice(0,2))}</span><button class="ticker" data-action="research" data-value="${esc(f.symbol)}">${esc(f.symbol)}</button>${badge(catLabel[f.category],f.tier==='CRITICAL'?'green':f.tier==='HIGH'?'amber':'')}</div><span class="time">${date(f.published_at)}</span></div><h2>${esc(headline)}</h2>${rich?.takeaway?`<p class="description">${esc(rich.takeaway)}</p>`:`<p class="description">${esc(f.detail||'Open the original exchange disclosure to review the details.')}</p>`}${rich?.financials?financialTable(rich.financials):''}${rich?.bio?`<div class="takeaway">${esc(rich.bio)}</div>`:''}${rich?.bio_items?`<div class="bio-box">${rich.bio_items.map(b=>`<div><span class="label">${esc(b.label)}</span><p>${esc(b.value)}</p></div>`).join('')}<a class="source-link" href="${esc(safeURL(rich.bio_source))}" target="_blank" rel="noopener noreferrer">Official career profile ${icon('external',11)}</a></div>`:''}${f.score===50?'<div class="tiny-note amber">Classification uncertain · retained for review</div>':''}<div class="card-footer">${rich?.evidence?source(rich.evidence):source({url:f.source_url,name:'Official NSE filing'})}<div class="card-actions"><button data-action="seen" data-value="${esc(f.id)}" aria-label="${seen?'Mark unread':'Mark reviewed'}">${icon('check',13)} <span class="review-text">${seen?'Reviewed':'Review'}</span></button>${pinButton(f.id)}</div></div></article>`}
function side(){const movers=Object.entries(data.prices).filter(([s])=>data.universe.some(r=>r.symbol===s&&r.group==='portfolio')).sort((a,b)=>Math.abs(b[1].metrics?.change_pct||0)-Math.abs(a[1].metrics?.change_pct||0)).slice(0,5);return `<aside class="right-panel"><div class="card audio-card"><button class="audio-orb" data-action="audio" aria-label="${playing?'Stop':'Play'} audio briefing">${icon(playing?'pause':'play',16)}</button><div><h3>Your commute, briefed.</h3><p>${playing?'Reading your material signals…':'A spoken brief of your top 3 signals'}</p></div></div><div class="card"><div class="aside-title"><h3>Portfolio pulse</h3><span class="label">EOD</span></div>${movers.map(([s,p])=>`<button class="watch-row" style="width:100%;text-align:left" data-action="research" data-value="${s}"><div><strong>${s}</strong><div class="tiny-note">₹${fmt(p.metrics.close,1)}</div></div>${spark(p.bars.slice(-20).map(b=>b.close),p.metrics.change_pct<0?'var(--red)':'var(--green2)')}<span class="num ${p.metrics.change_pct<0?'negative':'positive'}">${signed(p.metrics.change_pct)}%</span></button>`).join('')}<p class="tiny-note">Completed session: ${date(data.price_as_of)} · Yahoo Finance</p><button class="source-link" data-action="tab" data-value="alerts">Open anomaly watch ${icon('arrow',12)}</button></div><div class="card feature-card"><div class="label positive">THE DEEPER READ</div><h2>Management said it.<br>Did the numbers?</h2><p>Four quarters of KPIT promises, matched to primary disclosures. Currency, timing and accounting basis kept intact.</p><div class="feature-rule"></div><div style="display:flex;justify-content:space-between">${badge('KPITTECH','green')}<span class="tiny-note">Reviewed case study</span></div><button class="button" data-action="audit">Open the say–do audit ${icon('arrow',13)}</button><button class="source-link" data-action="replay" style="margin-top:12px">Replay KPIT’s result day ${icon('arrow',11)}</button></div><div class="tiny-note">${icon('shield',13)} No broker notes in Pull research.<br>Every conclusion has an evidence trail.<br><button class="source-link" data-action="about" style="margin-top:10px">What’s verified, and what isn’t ${icon('arrow',11)}</button></div></aside>`}
function feed(){const all=selectedFilings(),material=all.filter(f=>f.tier!=='LOW_NOISE'&&(state.category==='all'||f.category===state.category)),noise=all.filter(f=>f.tier==='LOW_NOISE');return `${head('Signal over noise.','The few things that deserve your attention. Everything else, out of the way.')}${summary(all)}<div class="columns"><section><div class="filters"><div class="segments" aria-label="Digest time window">${[[24,'24h'],[72,'3 days'],[168,'7 days'],['custom','Custom']].map(([v,t])=>`<button class="${state.window===v?'active':''}" data-action="window" data-value="${v}" aria-pressed="${state.window===v}">${t}</button>`).join('')}</div><select id="category" class="filter-select" aria-label="Filter filing category"><option value="all">All categories</option>${Object.entries(catLabel).map(([v,l])=>`<option value="${esc(v)}" ${state.category===v?'selected':''}>${esc(l)}</option>`).join('')}</select></div>${state.window==='custom'?`<div class="date-range"><label class="tiny-note">From <input type="date" id="from" value="${state.from}"></label><label class="tiny-note">Through <input type="date" id="to" value="${state.to}"></label><button class="button small-btn" data-action="apply-dates">Apply dates</button></div>`:''}<div class="stream-label label"><span><span class="dot"></span>Priority stream</span><span>${material.length} signals · ranked by materiality</span></div>${material.length?material.map(filingCard).join(''):`<div class="empty">${icon('check',28)}<h3>A quiet window.</h3><p>No material filings matched this selection.</p><button class="button" data-action="window" data-value="168">Look back 7 days</button></div>`}<details class="noise"><summary>${noise.length} routine filings tucked away <span class="tiny-note"> · fully auditable</span></summary>${noise.map(f=>`<div class="noise-item"><span>${esc(f.symbol)}</span><a href="${esc(safeURL(f.source_url))}" target="_blank" rel="noopener noreferrer">${esc(f.headline)} <span class="tiny-note">${date(f.published_at)}</span></a></div>`).join('')||'<p class="small muted" style="padding:0 16px">No routine filings in this window.</p>'}</details><p class="tiny-note">Counts reflect the selected window in the saved dataset. A missing filing is not proof that no disclosure exists.</p></section>${side()}</div>${footer()}<button class="mobile-audio mobile-only" data-action="audio">${icon(playing?'pause':'headphones',17)} ${playing?'Stop brief':'Listen to brief'}</button>`}
function computeMetrics(p){const bars=p?.bars||[];if(bars.length<2)return {};const close=bars.at(-1).close,prev=bars.at(-2).close,base=bars.slice(-21,-1);const avg=base.length===20?base.reduce((s,b)=>s+b.volume,0)/20:null;return {close,date:bars.at(-1).date,change_pct:prev>0?(close/prev-1)*100:null,rvol:avg>0?bars.at(-1).volume/avg:null}}
function alerts(){const rows=data.universe.filter(r=>r.group==='portfolio').map(r=>({symbol:r.symbol,...computeMetrics(data.prices[r.symbol])})).filter(r=>Math.abs(r.change_pct||0)>=state.settings.price_threshold_pct||(r.rvol||0)>=state.settings.volume_multiplier_threshold);const enabled=selectedFilings().filter(f=>state.settings.categories.includes(f.category)&&f.tier!=='LOW_NOISE');return `${head('Watch what matters.','Your thresholds. Your material events. No unexplained alerts.','settings','Tune thresholds')}<div class="columns"><section><div class="card"><div class="aside-title"><h3>Your anomaly rules</h3>${badge('Saved on this device','green')}</div><div class="slider-row"><div class="slider-label"><span>Absolute daily price move</span><strong class="mono" id="price-label">±${fmt(state.settings.price_threshold_pct)}%</strong></div><input id="price-slider" type="range" min="1" max="10" step="0.5" value="${state.settings.price_threshold_pct}" aria-label="Price change threshold"><div class="tiny-note">Trigger when the completed-session move reaches this threshold.</div></div><div class="slider-row"><div class="slider-label"><span>Relative trading volume</span><strong class="mono" id="volume-label">${fmt(state.settings.volume_multiplier_threshold)}×</strong></div><input id="volume-slider" type="range" min="1.5" max="5" step="0.1" value="${state.settings.volume_multiplier_threshold}" aria-label="Relative volume threshold"><div class="tiny-note">Compared with the preceding 20 sessions, excluding the alert day.</div></div><div class="label" style="margin-top:18px">Announcement alerts</div><div class="category-grid">${Object.entries(catLabel).map(([v,l])=>`<button class="category-toggle ${state.settings.categories.includes(v)?'active':''}" data-action="toggle-category" data-value="${esc(v)}" aria-pressed="${state.settings.categories.includes(v)}">${esc(l)}</button>`).join('')}</div></div><div class="section-title"><h2>${rows.length} price / volume triggers</h2><span class="tiny-note">EOD ${date(data.price_as_of)}</span></div>${rows.map(r=>{const end=new Date(`${r.date}T15:30:00+05:30`);const filing=data.filings.filter(f=>f.symbol===r.symbol&&f.tier!=='LOW_NOISE'&&new Date(f.published_at)<=end&&new Date(f.published_at)>=new Date(end-48*3600000)).sort((a,b)=>b.score-a.score)[0];return `<article class="card"><div class="card-head"><button class="ticker" data-action="research" data-value="${r.symbol}">${r.symbol}</button>${badge(r.rvol>=state.settings.volume_multiplier_threshold?'VOLUME TRIGGER':'PRICE TRIGGER','amber')}</div><div class="anomaly-value mono">₹${fmt(r.close,2)} <span class="small ${r.change_pct<0?'negative':'positive'}">${signed(r.change_pct)}%</span></div><div class="anomaly-detail"><span class="mono small amber">${fmt(r.rvol)}× volume</span><div class="bar"><span style="width:${Math.min(100,(r.rvol||0)/5*100)}%"></span></div></div><div class="takeaway">${filing?`<div class="label">Related disclosure · previous 48 hours</div><p>${esc(filing.headline)}</p>${source({url:filing.source_url,name:'Open exchange filing'})}`:'No material filing found in the captured 48-hour window. Source coverage may be incomplete.'}</div><p class="tiny-note">${filing?'Timing overlap is not evidence of causation.':'No causal explanation is inferred from missing data.'} Corporate actions can affect raw price and volume comparisons.</p></article>`}).join('')||'<div class="empty"><h3>No threshold breaches.</h3><p>Try a lower threshold to inspect the captured session.</p></div>'}<div class="section-title"><h2>${enabled.length} selected-category alerts</h2><span class="tiny-note">Current digest window</span></div>${enabled.slice(0,12).map(filingCard).join('')}${enabled.length>12?'<p class="tiny-note">Showing the 12 highest-priority alerts; the full stream is in Push digest.</p>':''}</section>${side()}</div>${footer()}`}
function moduleHead(n,title,id){return `<div class="section-title"><h2><span class="index mono">${String(n).padStart(2,'0')}</span>${title}</h2><div class="card-actions">${pinButton(id)}</div></div>`}
function insight(f){return `<div class="insight"><span class="insight-dot"></span><div><p>${esc(f.text)}</p>${source(f.evidence)}</div></div>`}
function audit(d){return `${moduleHead(6,'Narrative vs. numbers','module-audit')}<div class="card important"><div class="review-head">${badge('4-QUARTER SAY–DO AUDIT','green')}<span class="tiny-note">Reviewed primary-source case</span></div><p class="description">Annual promises stay annual. Organic growth stays separate from acquired growth. Unscorable statements stay unscored.</p>${d.audit.map(a=>`<div class="audit-row"><div><div class="audit-period mono">${esc(a.quarter)}</div><div class="tiny-note">${esc(a.period_label||'Outcome quarter')}</div></div><div class="audit-copy"><div class="label">Management said</div><div class="said">“${esc(a.promise)}”</div>${source(a.promise_evidence)}<div class="delivered"><div class="label">What followed</div>${esc(a.delivered)}</div>${source(a.outcome_evidence)}<p class="audit-note">${esc(a.note)}</p>${badge(a.verdict,a.verdict==='MISSED'?'red':a.verdict==='SUPPORTED'?'green':'amber')}</div></div>`).join('')}<div class="notice"><strong>One matured numeric commitment:</strong> ${esc(d.commitment.text)}<div style="margin-top:8px">${source(d.commitment.promise)} · ${source(d.commitment.outcome)}</div></div><div class="audit-score"><div><strong>0 / 1</strong><div class="tiny-note">Comparable numeric commitments met</div></div><div class="tiny-note" style="max-width:220px">One observation is too small for a reliable management credibility rating. Qualitative and open commitments are excluded.</div></div></div>`}
function researchView(){const s=state.symbol,d=data.dossiers?.[s],company=liveResearch?.query_symbol===s?liveResearch.company:data.companies[s],p=data.prices[s],tabs=['dossier','audit','sources'];return `${head('Follow the evidence.','On-demand research, grounded in company disclosures.')}<form id="search-form" class="research-search"><input id="ticker-input" autocomplete="off" aria-label="NSE ticker or BSE code" placeholder="Search any NSE ticker, e.g. POLYCAB" value="${esc(s)}"><button class="button primary" type="submit">${icon('search',15)}Research</button></form><div class="suggestions">${['KPITTECH','SONACOMS','TCS','ETERNAL','NH','POLYCAB'].map(x=>`<button data-action="research" data-value="${x}" class="${s===x?'selected':''}">${x}</button>`).join('')}</div><div class="columns"><section><div class="card-head"><div><h2>${esc(company?.name||data.universe.find(r=>r.symbol===s)?.name||s)}</h2><span class="tiny-note">${s} · ${d?'Reviewed primary-source dossier':'Source discovery pack'}</span></div>${badge(d?'PRIMARY EVIDENCE':'COVERAGE FIRST',d?'green':'amber')}</div><div class="research-tabs">${tabs.map(t=>`<button data-action="research-tab" data-value="${t}" class="${state.researchTab===t?'active':''}">${({dossier:'Company dossier',audit:'Say–do audit',sources:'Source ledger'})[t]}</button>`).join('')}</div>${state.researchTab==='sources'?sourceLedger(company,d):state.researchTab==='audit'?(d?audit(d):missingResearch(company)):d?dossier(d,p):genericResearch(company,p)}</section>${side()}</div>${footer()}`}
function dossier(d,p){const fin=d.financials,rev=fin.rows.find(r=>r.key==='revenue'),margin=fin.rows.find(r=>r.key==='margin'),pat=fin.rows.find(r=>r.key==='pat');return `${moduleHead(1,'Business, in a minute','module-business')}<div class="card">${d.business.map(insight).join('')}</div>${moduleHead(2,'The financial snapshot','module-financial')}<div class="metric-grid">${[['Revenue',`₹${fmt(rev.values[0],1)} Cr`,fin.periods[0]],['Reported EBITDA margin',`${fmt(margin.values[0],2)}%`,`${signed(margin.qoq,0)} bps QoQ`],['PAT',`₹${fmt(pat.values[0],1)} Cr`,'Includes non-controlling interests'],['Net cash',`₹${fmt(d.balance.net_cash,1)} Cr`,d.balance.period],['Borrowings / equity',`${fmt(d.balance.de,2)}×`,'Excludes lease liabilities'],['Price',p?`₹${fmt(p.metrics.close,2)}`:'Unavailable',p?`Yahoo · ${date(p.metrics.date)}`:'Provider unavailable']].map(([l,v,f])=>`<div class="metric-cell"><div class="label">${l}</div><div class="value mono">${v}</div><div class="footnote">${f}</div></div>`).join('')}</div><div style="margin:10px 0">${source('kpit-financial')} · ${source('kpit-balance')}</div><details class="noise"><summary>Open the full quarterly comparison</summary><div style="padding:0 15px 15px">${financialTable(fin)}</div></details>${moduleHead(3,'The trajectory','module-trajectory')}<div class="card"><div class="card-head"><h3>${state.trajectory==='quarterly'?'Revenue, ₹ crore':'Revenue, US$ million'}</h3><div class="segments"><button data-action="trajectory" data-value="quarterly" class="${state.trajectory==='quarterly'?'active':''}">Quarterly</button><button data-action="trajectory" data-value="annual" class="${state.trajectory==='annual'?'active':''}">Annual</button></div></div>${chart(state.trajectory==='quarterly'?d.trajectory.quarters:d.trajectory.annual,state.trajectory==='quarterly'?'₹ Cr':'US$ million')}${state.trajectory==='annual'?annualMetrics(d.trajectory.annual_metrics):''}<div class="takeaway">${esc(state.trajectory==='quarterly'?d.trajectory.quarter_note:d.trajectory.annual_note)}</div><p class="tiny-note">${source(state.trajectory==='quarterly'?'kpit-financial':'kpit-five-year')}</p></div>${moduleHead(4,'Balance sheet & working capital','module-balance')}<div class="card"><div class="balance-flow"><div><strong class="mono">${fmt(d.balance.debt,1)}</strong><span>Borrowings · ₹ Cr</span></div><span>→</span><div><strong class="mono">${fmt(d.balance.cash,1)}</strong><span>Gross cash · ₹ Cr</span></div><span>→</span><div><strong class="mono positive">${fmt(d.balance.net_cash,1)}</strong><span>Net cash · ₹ Cr</span></div></div><p class="description">${esc(d.balance.note)}</p>${source('kpit-balance')}<div class="notice">DSO: ${d.balance.dso} days. A complete cash-conversion cycle is unavailable: comparable inventory and payable days were not extracted. DSO is not the full working-capital cycle.</div>${source('kpit-cash')}</div>${moduleHead(5,'Do profits turn into cash?','module-cash')}<div class="card"><div class="review-head"><h3>Cash conversion, with the right denominator</h3>${badge(d.cash?.ratio!=null?`${fmt(d.cash.ratio*100,0)}%`:'COVERAGE GAP',d.cash?.ratio==null?'amber':d.cash.ratio>.8?'green':d.cash.ratio>=.6?'amber':'red')}</div>${d.cash?.ratio!=null?`<div class="balance-flow"><div><strong class="mono">₹${fmt(d.cash.cfo,0)}</strong><span>${d.cash.period} CFO · Cr</span></div><div><strong class="mono">₹${fmt(d.cash.ebitda,0)}</strong><span>Reported EBITDA · Cr</span></div><div><strong class="mono positive">₹${fmt(d.cash.fcf,0)}</strong><span>FCF · Cr</span></div></div>${cashChart(d.cash.years)}<p class="description">${esc(d.cash.note)}</p>${source(d.cash.evidence)} · ${source(d.cash.previous_evidence)} · ${source('kpit-five-year')}`:`${cashChart(d.cash.years)}<p class="description">${esc(d.cash.note)}</p>`}<div class="notice">Traffic light: green >80%, amber 60–80%, red <60%. The separate forensic screen flags cumulative conversion below 70%; these thresholds are deliberately distinct.</div></div>${audit(d)}${moduleHead(7,'Forward guidance tracker','module-guidance')}<div class="card">${d.guidance.map(g=>`<div class="insight"><div><div class="review-head"><h3>${esc(g.title)}</h3>${badge(g.status,'amber')}</div><p>${esc(g.text)}</p>${source(g.evidence)}</div></div>`).join('')}</div>${moduleHead(8,'The case, both ways','module-debate')}<div class="two-grid"><div class="card"><h3 class="positive">The bull case</h3>${d.bull.map(insight).join('')}</div><div class="card"><h3 class="negative">The bear case</h3>${d.bear.map(insight).join('')}</div></div><div class="section-title"><h2>${icon('shield',17)} Governance watch</h2></div><div class="card">${d.governance.map(insight).join('')}<p class="tiny-note">An unreviewed note is unknown, not a clean bill of health.</p></div>`}
function chart(rows,unit="₹ Cr"){if(!rows?.length)return '<p class="muted">Comparable primary figures not yet extracted.</p>';const max=Math.max(...rows.map(r=>r.value));return `<div class="bar-chart" role="img" aria-label="Revenue ${rows.map(r=>`${r.label} ${fmt(r.value,1)} ${unit}`).join(', ')}">${rows.map(r=>`<div class="chart-column" style="height:${r.value/max*100}%"><span class="chart-value mono">${fmt(r.value,0)}</span><span class="chart-label">${esc(r.label)}</span></div>`).join('')}</div>`}
function cashChart(rows){if(!rows?.length)return '';const max=Math.max(...rows.flatMap(r=>[r.cfo,r.ebitda]));return `<div class="cash-chart" aria-label="Annual CFO and EBITDA in rupees crore">${rows.map(r=>`<div class="cash-chart-row"><strong>${r.label}</strong><div><div class="cash-bar" style="width:${r.cfo/max*100}%"><span>CFO ${fmt(r.cfo,1)}</span></div><div class="cash-bar earnings" style="width:${r.ebitda/max*100}%"><span>EBITDA ${fmt(r.ebitda,1)}</span></div></div></div>`).join('')}</div>`}
function annualMetrics(rows){return rows?.length?`<div class="table-scroll"><table class="financial-table"><thead><tr><th>Primary annual ratios</th>${rows.map(r=>`<th>${r.year}</th>`).join('')}</tr></thead><tbody><tr><td>EBITDA margin</td>${rows.map(r=>`<td>${fmt(r.margin)}%</td>`).join('')}</tr><tr><td>ROE</td>${rows.map(r=>`<td>${fmt(r.roe)}%</td>`).join('')}</tr></tbody></table></div><p class="tiny-note">FY26 margin −20 bps and ROE −1,080 bps versus FY25, on rounded company disclosures. Currency growth and return ratios measure different things.</p>`:''}
function missingResearch(c){return `<div class="empty">${icon('book',28)}<h3>Evidence before a verdict.</h3><p>${c?'Primary documents have been discovered. A reviewed four-quarter audit is not yet available for this company.':'This company is outside the saved source packs.'}</p><p class="small">${backend?'Run the live research pipeline to download primary documents. Optional model synthesis requires server-side model credentials.':'Start the included backend for arbitrary-ticker ingestion and optional model synthesis.'}</p><button class="button" data-action="live-research">${icon('search',14)} ${backend?'Run primary research':'Connect research backend'}</button></div>`}
function genericResearch(c,p){const f=liveResearch?.query_symbol===state.symbol?liveResearch.financials:null;return `${p?`<div class="card"><div class="label">MARKET DATA · YAHOO FINANCE</div><div class="anomaly-value mono">₹${fmt(p.metrics.close,2)} <span class="small ${p.metrics.change_pct<0?'negative':'positive'}">${signed(p.metrics.change_pct)}%</span></div>${spark(p.bars.map(b=>b.close))}<p class="tiny-note">${date(p.metrics.date)} completed session. Market quotes are not company fundamentals.</p></div>`:''}${f?`<div class="card">${financialTable(f)}${source(f.source)}</div>`:''}${missingResearch(c)}${liveResearch?.query_symbol===state.symbol?renderModelAnalysis(liveResearch):''}<div class="section-title"><h2>Primary document discovery</h2></div>${sourceLedger(c,null)}`}
function renderModelAnalysis(r){const a=r.analysis;if(!a)return `<p class="notice">${r.coverage?.downloaded||0} documents downloaded · ${r.coverage?.transcripts||0} transcripts. Synthesis: ${esc(r.analysis_status)}. ${r.source_failures?.length||0} sources could not be retrieved.</p>`;const ref=c=>{const doc=r.documents.find(d=>d.id===c.document_id);return source({url:doc?.url,name:doc?.name,page:c.page})};return `<div class="notice">${esc(a.warning)}</div>${['business','guidance','bull','bear','governance'].map(k=>`<div class="card"><h3>${k.toUpperCase()}</h3>${a[k].map(f=>`<p>${esc(f.claim)}</p>${ref(f.citation)}`).join('')||'<p class="muted">No supported findings.</p>'}</div>`).join('')}<div class="card"><h3>Model-assisted say–do audit</h3>${a.audit.map(row=>`<div class="audit-row"><span>${esc(row.quarter_label)}</span><div><p>${esc(row.promised_guidance_quote)}</p>${ref(row.promise)}<p>${esc(row.metric)}: ${fmt(row.actual)} ${esc(row.unit)} · ${esc(row.status)}</p>${row.outcome?ref(row.outcome):''}</div></div>`).join('')||'<p class="muted">No comparable commitments extracted.</p>'}</div>`}
function sourceLedger(c,d){const refs=d?Object.entries(data.evidence).filter(([,v])=>v.symbol===state.symbol):[];return `<div class="card"><div class="review-head"><h3>Open the underlying evidence</h3>${badge(d?'Page-level citations':'Discovered links')}</div><p class="tiny-note">${d?'Page numbers refer to PDF pages, including cover sheets.':'Discovery is not validation. A listed document may be unavailable or may contain only a notice.'}</p>${refs.map(([id,e])=>`<div class="document-row"><button class="source-link" data-action="evidence" data-value="${id}">${icon('book',13)}${esc(e.label)}</button><span>PDF p. ${e.page}</span></div>`).join('')}${!d?(c?.documents||[]).map(e=>`<div class="document-row"><a href="${esc(safeURL(e.url))}" target="_blank" rel="noopener noreferrer">${esc(e.name)} ${icon('external',12)}</a><span>${esc(e.kind.replace('_',' '))}</span></div>`).join(''):''}${!d&&!c?.documents?.length?'<p class="muted">No saved documents. Connect the backend to retrieve them.</p>':''}${c?`<p class="tiny-note" style="margin-top:18px">Document discovery: <a href="${esc(safeURL(c.source_url))}" target="_blank" rel="noopener noreferrer">Screener</a> · captured ${date(c.fetched_at)}. Its normalized tables are excluded from primary-only conclusions.</p>`:''}</div>`}
function portfolio(){return `${head('Your conviction, organised.','18 portfolio companies. Four research names. An evidence trail you can keep.','export','Export IC note')}<div class="research-tabs"><button class="${state.portfolioTab==='watchlist'?'active':''}" data-action="portfolio-tab" data-value="watchlist">Watchlist · 18</button><button class="${state.portfolioTab==='pins'?'active':''}" data-action="portfolio-tab" data-value="pins">Thesis pinboard · ${state.pins.length}</button><button data-action="telemetry">Routing & cost ${icon('external',11)}</button></div>${state.portfolioTab==='watchlist'?`<div class="card"><div style="overflow-x:auto"><table class="universe-table"><thead><tr><th>Company</th><th class="sector-col">Sector</th><th class="spark-col">20 sessions</th><th class="num">Close, ₹</th><th class="num">Day</th></tr></thead><tbody>${data.universe.map((r,i)=>{const p=data.prices[r.symbol],m=p?.metrics||{};return `${i===18?'<tr><td colspan="5" class="label" style="padding-top:25px">Ad-hoc research universe</td></tr>':''}<tr><td><button class="ticker" data-action="research" data-value="${r.symbol}">${r.symbol}</button><div class="tiny-note">${esc(r.name)}</div></td><td class="sector-col muted">${esc(r.sector)}</td><td class="spark-col">${spark(p?.bars.slice(-20).map(b=>b.close)||[],m.change_pct<0?'var(--red)':'var(--green2)')}</td><td class="num">${fmt(m.close,2)}</td><td class="num ${m.change_pct<0?'negative':'positive'}">${signed(m.change_pct)}${m.change_pct!=null?'%':''}</td></tr>`}).join('')}</tbody></table></div><p class="tiny-note">Market-cap tiers are illustrative portfolio selections, not a current regulatory classification. EOD data through ${date(data.price_as_of)}.</p></div>`:`<div class="card"><div class="review-head"><h3>Investment Committee working note</h3><button class="button small-btn" data-action="export">${icon('download',12)}Export</button></div><p class="tiny-note">Add your own interpretation beside each pinned source. Pins persist on this browser.</p>${state.pins.length?state.pins.map(p=>`<article class="pin-card"><div class="review-head">${badge(p.symbol,'green')}<button class="icon-button" data-action="pin" data-value="${esc(p.id)}" aria-label="Remove pinned finding">${icon('trash',14)}</button></div><h3>${esc(p.title)}</h3>${source({url:p.source_url,name:p.source_label||'Evidence'})}<textarea data-pin-note="${esc(p.id)}" aria-label="Your thesis note for ${esc(p.symbol)}" placeholder="Your interpretation. What would change your mind?">${esc(p.note||'')}</textarea></article>`).join(''):'<div class="empty"><h3>Build a thesis from evidence.</h3><p>Pin a filing or research module, then add your own judgment here.</p><button class="button" data-action="tab" data-value="feed">Explore the briefing</button></div>'}</div>`}${footer()}`}
function render(){document.body.classList.toggle('light',state.theme==='light');document.body.classList.toggle('compact',state.compact);$('#app').innerHTML=`<header class="topbar"><a class="brand" href="#" data-action="tab" data-value="feed" aria-label="FINN home"><span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i></span>FINN<span class="brand-sub">Financial investment intelligence</span></a><div class="top-actions"><button class="badge green" data-action="telemetry">${icon('bolt',11)}<span>${backend?'Routing & cost':'$0 model spend'}</span></button><button class="icon-button desktop-only" data-action="compact" aria-label="Toggle phone preview">${icon('phone',17)}</button><button class="icon-button" data-action="theme" aria-label="Toggle light or dark theme">${icon('sun',17)}</button><button class="icon-button" data-action="connection" aria-label="Source and backend settings">${icon('settings',17)}</button><span class="avatar" aria-label="Single-user workspace">PK</span></div></header><div class="shell"><aside class="sidebar"><div class="label" style="padding:0 14px 15px">YOUR WORKSPACE</div>${nav()}<div class="sidebar-foot"><div class="signal-lines">${'<i></i>'.repeat(12)}</div><strong style="color:var(--text);font-weight:500">Less noise.<br>More conviction.</strong><p>Built around the evidence.</p><button class="source-link" data-action="about">About this build ${icon('external',10)}</button></div></aside><main class="workspace" id="main">${({feed,alerts,research:researchView,portfolio})[state.tab]()}</main></div><nav class="bottom-nav" aria-label="Primary navigation">${Object.entries(names).map(([k,n])=>`<button data-action="tab" data-value="${k}" class="${state.tab===k?'active':''}" ${state.tab===k?'aria-current="page"':''}>${icon(({feed:'feed',alerts:'bolt',research:'search',portfolio:'grid'})[k])}${({feed:'Digest',alerts:'Alerts',research:'Research',portfolio:'Portfolio'})[k]}</button>`).join('')}</nav>`}
function evidence(id){const e=data.evidence[id];if(!e)return toast('Evidence reference unavailable.');modal(e.label,`${badge('PRIMARY COMPANY DISCLOSURE','green')}<p class="small muted">${esc(e.symbol)} · PDF page ${e.page} · captured ${date(data.as_of)}</p>${e.quote?`<div class="quote">“${esc(e.quote)}”</div>`:''}<p>${esc(e.note||'Figures are transcribed from this primary disclosure. Open the page to inspect the underlying table.')}</p><div class="source-hash">SHA-256: ${esc(e.hash)}</div><p style="margin-top:22px"><a class="button primary" href="${esc(safeURL(e.url))}#page=${e.page}" target="_blank" rel="noopener noreferrer">Open original PDF ${icon('external',13)}</a></p>`)}
function makePin(id){const f=[...data.filings,...(data.replay||[])].find(x=>x.id===id);if(f){const r=data.rich_filings?.[id];return {id,symbol:f.symbol,title:r?.headline||f.headline,source_url:f.source_url,source_label:'Official exchange filing',note:''}}const lookup={'module-business':['Business snapshot','kpit-business'],'module-financial':['Primary quarterly financial snapshot','kpit-financial'],'module-trajectory':['Revenue and reported EBITDA trajectory','kpit-financial'],'module-balance':['Debt, cash and working capital','kpit-balance'],'module-cash':['Cash quality: coverage and conversion','kpit-cash'],'module-audit':['Four-quarter management say–do audit','kpit-audit-q3'],'module-guidance':['Forward guidance and its evaluation horizon','kpit-guidance'],'module-debate':['Evidence-backed bull and bear case','kpit-financial']};if(!lookup[id])return null;const [title,ref]=lookup[id],e=data.evidence[ref];return {id,symbol:'KPITTECH',title,source_url:e.url+'#page='+e.page,source_label:e.label,note:''}}
function pin(id){const index=state.pins.findIndex(p=>p.id===id);if(index>=0){state.pins.splice(index,1);toast('Removed from thesis')}else{const p=makePin(id);if(!p)return;state.pins.unshift(p);toast('Pinned to your thesis')}saveStore('finn.pins',state.pins);render()}
async function persistSettings(){saveStore('finn.settings',state.settings);if(backend){try{await api('/api/settings',{method:'PUT',body:JSON.stringify(state.settings)})}catch(e){toast('Saved locally; backend sync failed.')}}}
async function searchSymbol(raw){const text=raw.trim().toUpperCase();const v=text.startsWith('BSE:')?text.slice(4)+'.BO':text.replace(/^NSE:/,'').replace(/\.NS$/,'');const s=({ZOMATO:'ETERNAL',NARAYANA:'NH'})[v]||v;if(!/^[A-Z0-9][A-Z0-9&.-]{0,29}$/.test(s)){toast('Enter a valid ticker, e.g. M&M or 500325.BO.');return}state.symbol=s;state.tab='research';state.researchTab='dossier';liveResearch=null;render();if(s!==v)toast(`${v} resolves to ${s}`);const sequence=++requestSequence;if(!data.companies[s]&&backend){busy=true;render();try{const c=await api('/api/company/'+encodeURIComponent(s));if(sequence!==requestSequence)return;data.companies[s]=c;const p=await api('/api/prices/'+encodeURIComponent(s));if(sequence!==requestSequence)return;if(p.bars?.length)data.prices[s]=p;toast('Live source pack retrieved')}catch(e){if(sequence===requestSequence)toast(e.message)}finally{if(sequence===requestSequence){busy=false;render()}}}window.scrollTo({top:0,behavior:'instant'})}
async function livePipeline(){if(!backend)return connection();const symbol=state.symbol;modal('Run source-grounded research',`<p>Download filings, presentations, annual reports and transcripts for <strong>${esc(symbol)}</strong>.</p><p class="tiny-note">Primary pages are hashed and parsed once. Unsupported tables remain unavailable. Model calls are optional and require server-side credentials.</p><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="button primary" data-action="run-research" data-value="false">Ingest & extract</button><button class="button" data-action="run-research" data-value="true">Include model synthesis</button></div>`)}
async function runResearch(models){$('#drawer').close();const sequence=++requestSequence;busy=true;render();toast('Reading primary documents. This can take a minute.');try{const r=await api('/api/research',{method:'POST',body:JSON.stringify({symbol:state.symbol,use_models:models})});if(sequence!==requestSequence)return;liveResearch={...r,query_symbol:state.symbol};data.companies[state.symbol]=r.company;if(r.price?.bars?.length)data.prices[state.symbol]={...r.price,metrics:computeMetrics(r.price)};toast(`${r.coverage.downloaded} source documents retrieved`)}catch(e){if(sequence===requestSequence)toast(e.message)}finally{if(sequence===requestSequence){busy=false;render()}}}
function connection(){modal('Research connection',`<div class="notice">The hosted site opens a real, dated market snapshot. The downloadable FastAPI app provides live ingestion, document parsing and optional model calls.</div><p class="small">Run <span class="mono">start.ps1</span> on Windows or <span class="mono">./start.sh</span> on macOS/Linux, then open <span class="mono">http://127.0.0.1:8000</span>. The local app connects automatically.</p><p class="small">For a separately deployed HTTPS backend, configure its allowed frontend origin and API token on the server.</p><label class="small">Backend HTTPS origin<input id="api-origin" type="url" placeholder="https://your-finn-api.example" value="${esc(state.api)}"></label><label class="small">API token (session only)<input id="api-token" type="password" autocomplete="off" value="${esc(apiToken)}"></label><div style="display:flex;gap:9px"><button class="button primary" data-action="connect">Connect & verify</button><button class="button" data-action="disconnect">Use saved snapshot</button></div><p class="tiny-note">Localhost from a hosted HTTPS page may be blocked by browser mixed-content rules. Open the local app directly instead.</p>`)}
async function connect(){let origin=$('#api-origin').value.trim().replace(/\/$/,'');try{if(origin&&!/^https:\/\//.test(origin))throw Error('Use an HTTPS backend origin, or open the local app directly.');state.api=origin;apiToken=$('#api-token').value;const h=await api('/api/health');if(h.status!=='ok')throw Error('Health check failed');backend=true;saveStore('finn.api',origin);sessionStorage.setItem('finn.token',apiToken);$('#drawer').close();toast('Research backend connected');render()}catch(e){backend=false;toast(e.message)}}
async function refresh(){if(!backend)return connection();busy=true;render();try{const result=await api('/api/refresh',{method:'POST'});const end=new Date(),start=new Date(end-120*86400000);const digest=await api('/api/digest?start='+encodeURIComponent(start.toISOString())+'&end='+encodeURIComponent(end.toISOString()));data.filings=digest.items;data.as_of=end.toISOString();await Promise.all(data.universe.filter(r=>r.group==='portfolio').map(async r=>{try{const p=await api('/api/prices/'+r.symbol);if(p.bars?.length)data.prices[r.symbol]=p}catch{}}));const dates=Object.values(data.prices).map(p=>p.metrics?.date).filter(Boolean).sort();data.price_as_of=dates.at(-1);toast(result.sources?.every(x=>x.filings==='fresh'&&x.prices==='fresh')?'Sources refreshed':'Refresh completed; some sources may be cached or unavailable')}catch(e){toast(e.message)}finally{busy=false;render()}}
function audioBrief(){if(!('speechSynthesis' in window))return toast('Speech playback is not supported in this browser.');if(playing){speechSynthesis.cancel();playing=false;render();return}const items=selectedFilings().filter(f=>f.tier!=='LOW_NOISE').slice(0,3);if(!items.length)return toast('No material signals to read in this window.');const text=`FINN portfolio briefing. Saved data as of ${date(data.as_of)}. ${items.map((f,i)=>`${i+1}. ${f.symbol}. ${data.rich_filings?.[f.id]?.headline||f.headline}. ${data.rich_filings?.[f.id]?.takeaway||f.detail}.`).join(' ')} Source documents are linked in your digest. This briefing reports disclosures, not investment recommendations.`;const u=new SpeechSynthesisUtterance(text);u.lang='en-IN';u.rate=.98;u.onend=u.onerror=()=>{playing=false;render()};speechSynthesis.cancel();speechSynthesis.speak(u);playing=true;render()}
function exportDialog(){modal('Export your IC working note',`<p>${state.pins.length} pinned finding${state.pins.length===1?'':'s'}, with your annotations and original source links.</p>${!state.pins.length?'<div class="notice">Pin evidence from the digest or a research module before exporting.</div>':''}<div style="display:flex;gap:10px;flex-wrap:wrap"><button class="button primary" data-action="download-memo" ${!state.pins.length?'disabled':''}>${icon('download',14)}Download Markdown</button><button class="button" data-action="print-memo" ${!state.pins.length?'disabled':''}>Print / save as PDF</button></div><p class="tiny-note">PDF uses your browser’s print dialog. Up to five pins are used for a concise working note; Markdown includes all pins.</p>`)}
function exportMemo(print=false){const pins=print?state.pins.slice(0,5):state.pins;if(!pins.length)return;if(print){document.querySelector('.print-memo')?.remove();const el=document.createElement('section');el.className='print-memo';el.innerHTML=`<h1>FINN / Investment Committee note</h1><p>Prepared ${new Date().toLocaleDateString('en-IN')} · Evidence captured ${date(data.as_of)}</p><p>Working research note. Conclusions and position sizing require investor judgment.</p>${pins.map(p=>`<article><strong>${esc(p.symbol)} · ${esc(p.title)}</strong><p>${esc(p.note||'No analyst annotation added.')}</p><a href="${esc(safeURL(p.source_url))}">${esc(p.source_url)}</a></article>`).join('')}<p>Open questions: What invalidates the thesis? What needs primary-source verification?</p>`;document.body.appendChild(el);$('#drawer').close();window.print();return}const text=`# FINN — Investment Committee working note\n\nCreated: ${new Date().toISOString()}\nEvidence snapshot: ${data.as_of}\n\nWorking research note; not an investment recommendation.\n\n${pins.map(p=>`## ${p.symbol}: ${p.title}\n\n${p.note||'_No analyst annotation added._'}\n\nSource: ${p.source_url}\n`).join('\n')}\n## Open questions\n- What invalidates the thesis?\n- Which evidence needs further verification?\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='FINN_IC_Note.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('IC note exported')}
async function telemetry(){let t;try{if(backend)t=await api('/api/telemetry')}catch{}modal('The routing ledger',`<p class="small muted">${t?'Actual requests recorded by the connected backend.':'Saved demo: deterministic extraction and a manually reviewed primary-source case. No model calls were made.'}</p><div class="metric-grid"><div class="metric-cell"><div class="label">MODEL SPEND</div><div class="value mono">$${fmt(t?.cost||0,4)}</div><div class="tiny-note">${t?'Known-price requests only':'No simulated token counts'}</div></div><div class="metric-cell"><div class="label">CACHE HITS</div><div class="value mono">${t?.cache_hits??'—'}</div><div class="tiny-note">${t?'Recorded cache reuse':'Live backend required'}</div></div></div><div class="telemetry-row"><span class="positive mono">T0</span><span>Rules, arithmetic, PDF/table parsing</span><span class="mono">$0</span></div><div class="telemetry-row"><span class="amber mono">T1</span><span>Ambiguous filing classification · optional</span><span class="mono">${t?'opt-in':'not run'}</span></div><div class="telemetry-row"><span class="mono">T2</span><span>Primary-source synthesis · optional</span><span class="mono">${t?'opt-in':'not run'}</span></div><p class="tiny-note">${t?.unpriced_calls?`${t.unpriced_calls} request(s) have no configured price and are excluded from the spend total. `:''}Model, prompt, schema and source text are part of the cache key. Costs need configured provider prices; unpriced calls are not represented as free.</p>${t?.requests?.slice(0,12).map(r=>`<div class="telemetry-row"><span class="mono">T${r.tier}</span><span>${esc(r.task)} · ${esc(r.status)}${r.cache_hit?' · cache hit':''}</span><span class="mono">${fmt(r.latency_ms,0)} ms</span></div>`).join('')||''}<p class="tiny-note">Network fetch latency depends on provider availability. No claim of a measured 300 ms cold start.</p>`)}
function about(){modal('Built around evidence',`<p>FINN is a working research prototype for the ENAM AI Engineer Build Challenge.</p><div class="notice">This hosted view uses genuine saved exchange filings, public price bars and discovered company documents, captured on ${date(data.as_of)}. It does not run an unattended live market feed.</div><p class="small"><strong>Verified here:</strong> 18 portfolio stocks, 4 ad-hoc stocks, source-linked filing triage, EOD rules, a reviewed KPIT research dossier, primary results cards, audio, pins and export.</p><p class="small"><strong>Portable backend:</strong> arbitrary ticker ingestion, SQLite cache, PDF extraction, optional model routing, cited research, executive background search, API and scheduled polling.</p><p class="small"><strong>Limits:</strong> provider blocks can occur; scanned pages need OCR and review; unextracted data stays unavailable; the curated dossier is not automatically a complete audit of every note. Browser voice duration varies with the selected signals.</p><p class="small">Screener aggregates are retained as discovery aids, never passed off as primary-company financial evidence.</p><p><a class="button" href="/FINN_Source.zip" download>${icon('download',14)}Download source & submission notes</a></p>`)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const a=b.dataset.action,v=b.dataset.value;if(a==='tab'){state.tab=v;render();window.scrollTo(0,0)}else if(a==='window'){state.window=v==='custom'?v:Number(v);render()}else if(a==='apply-dates'){if($('#from').value>$('#to').value)return toast('The start date must precede the end date.');state.from=$('#from').value;state.to=$('#to').value;render()}else if(a==='theme'){state.theme=state.theme==='dark'?'light':'dark';saveStore('finn.theme',state.theme);render()}else if(a==='compact'){state.compact=!state.compact;render()}else if(a==='seen'){state.seen=state.seen.includes(v)?state.seen.filter(x=>x!==v):[...state.seen,v];saveStore('finn.seen',state.seen);render()}else if(a==='pin')pin(v);else if(a==='research')await searchSymbol(v);else if(a==='replay'){modal('KPIT · 29 July 2026 disclosure replay',`<p class="tiny-note">Historical source documents, not today’s announcements. One filing contains two material events; the raw digest counts the document once.</p>${data.replay.map(filingCard).join('')}`);}else if(a==='audit'){state.tab='research';state.symbol='KPITTECH';state.researchTab='audit';render();window.scrollTo(0,0)}else if(a==='research-tab'){state.researchTab=v;render()}else if(a==='portfolio-tab'){state.portfolioTab=v;render()}else if(a==='trajectory'){state.trajectory=v;const top=window.scrollY;render();window.scrollTo(0,top)}else if(a==='evidence')evidence(v);else if(a==='close')$('#drawer').close();else if(a==='toggle-category'){state.settings.categories=state.settings.categories.includes(v)?state.settings.categories.filter(c=>c!==v):[...state.settings.categories,v];await persistSettings();render()}else if(a==='settings'){state.tab='alerts';render();window.scrollTo(0,0)}else if(a==='audio')audioBrief();else if(a==='connection')connection();else if(a==='connect')await connect();else if(a==='disconnect'){state.api='';apiToken='';backend=false;saveStore('finn.api','');sessionStorage.removeItem('finn.token');$('#drawer').close();toast('Saved snapshot mode');render()}else if(a==='refresh')await refresh();else if(a==='live-research')await livePipeline();else if(a==='run-research')await runResearch(v==='true');else if(a==='export')exportDialog();else if(a==='download-memo')exportMemo();else if(a==='print-memo')exportMemo(true);else if(a==='telemetry')await telemetry();else if(a==='about')about()});
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();searchSymbol($('#ticker-input').value)}});
document.addEventListener('input',e=>{if(e.target.id==='price-slider')$('#price-label').textContent='±'+fmt(Number(e.target.value))+'%';if(e.target.id==='volume-slider')$('#volume-label').textContent=fmt(Number(e.target.value))+'×';if(e.target.dataset.pinNote){const p=state.pins.find(x=>x.id===e.target.dataset.pinNote);if(p){p.note=e.target.value;saveStore('finn.pins',state.pins)}}});
document.addEventListener('change',async e=>{if(e.target.id==='category'){state.category=e.target.value;render()}else if(['price-slider','volume-slider'].includes(e.target.id)){state.settings[e.target.id==='price-slider'?'price_threshold_pct':'volume_multiplier_threshold']=Number(e.target.value);await persistSettings();render()}});
$('#drawer').addEventListener('click',e=>{if(e.target===$('#drawer')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
async function init(){try{const response=await fetch('/data/snapshot.json');if(!response.ok)throw Error('The saved dataset could not be opened.');data=await response.json();try{const h=await api('/api/health',{signal:AbortSignal.timeout(2000)});backend=h.status==='ok'}catch{}render();if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{})}catch(e){$('#app').innerHTML=`<div class="loading"><div>FINN<p class="small negative">${esc(e.message)}</p><button class="button" onclick="location.reload()">Try again</button></div></div>`}}
init();
